// If you want to customaize this shader you can easily tweak these values
float CharArray[7] = float[7] (163.0, 177.0, 189.0, 163.0, 165.0, 190.0, 183.0); // S A M S U N G
float TextLength = 7.;

vec3 BgCol = vec3(0.2, 0.5, 0.2);

vec2 TextScale = vec2(3.0, 1.5); // A bigger nummber = smaller text
vec2 TextSpeed = vec2(0.5, 1.2);

vec3 BounceColor[2] = vec3[2]( vec3(1., 0., 0.) , vec3(0., 0., 1.) );

// Antialliasing settings
const int AntiAlliasingPoints = 9;

vec2 AntiAlliasingOffset[AntiAlliasingPoints] = vec2[AntiAlliasingPoints](
vec2(-0.707, 0.707),  vec2(0.0, 1.0),  vec2(0.707, 0.707),
vec2(-1.0, 0.0),      vec2(0.0, 0.0),  vec2(1.0, 0.0),
vec2(-0.707, -0.707), vec2(0.0, -1.0), vec2(0.707, -0.707)
);

float TimeOffset = 12.4;

// these are constants for math opperations, changing these may break the shader
const float ReciprocalPi = 0.3183098861;
const float HalfPi = 1.571;




vec3 CharRetrive(vec2 uv, float CharNr)
{
    uv *= 0.0625;

    vec2 CharUv = vec2( mod(CharNr, 16.) * 0.0625, floor(CharNr * 0.0625) * 0.0625 ) + uv;

    vec3 ImageColor = dot(vec3(1.,0.,0.), texture(iChannel0, CharUv).xyz) * vec3(1.,1.,1.);

    return ImageColor;
}

vec3 BackgroundRender(vec2 uv, vec3 Color) {
    return Color * distance(vec2(0.,0.), uv - 0.5) * 0.05;
}

vec3 RenderPass(vec2 uv, float Time)
{ 
    vec2 TextPos = vec2(acos(cos(Time * TextSpeed.x)), acos(cos(Time * TextSpeed.y))) * TextScale * ReciprocalPi;
    TextPos *= vec2(1. - (2./TextLength), 0.94);
    TextPos -= vec2(0.04, 0.03);

    vec2 TextureUv = vec2( clamp((uv.x * TextScale.x) - TextPos.x, 0., 1.), clamp((uv.y * TextScale.y) - TextPos.y, 0., 1.) );

    vec3 DynamicColor = BounceColor[0] * (atan(tan(-Time * TextSpeed.x + HalfPi)) + HalfPi);
    DynamicColor += BounceColor[1] * (atan(tan((-Time) * TextSpeed.y + HalfPi)) + HalfPi);



    if (TextureUv.x < 0.01 || TextureUv.y < 0.01 || TextureUv.x > 0.99 || TextureUv.y > 0.142) {
    return BackgroundRender(uv, DynamicColor);
    }

    float Offset = floor(TextureUv.x*7.);
    float Char = CharArray[int(Offset)] - Offset;

    vec3 TextureReturn = CharRetrive(TextureUv * 7.04, Char);

    if (TextureReturn.x < 0.2) {
    return BackgroundRender(uv, DynamicColor);
    }

    return TextureReturn * DynamicColor;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    float Time = iTime + TimeOffset;

    vec3 col = vec3(0.,0.,0.);
    float ColorWeight = 1./float(AntiAlliasingPoints);

    for (int i = 0; i < AntiAlliasingPoints; i++) {
        vec2 iuv = uv + AntiAlliasingOffset[i] * 0.0015;
        col += RenderPass(iuv, Time) * ColorWeight;
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
